/* nodes details for region "circuits", loaded on demand by atlas/app.js (ATLAS.loadDetails). */
window.ATLAS.addDetails("circuits.nodes",{"nodes":{
"magnets":{"description":{"zh":"磁场在磁极附近最强，磁感线从 N 极出、进 S 极，异极相吸同极相斥。点磁极、平方反比的简化模型。","en":"The field is strongest near the poles, field lines leave N and enter S, unlike poles attract and like poles repel. A simplified point-pole inverse-square model."},"formula":"B ∝ q / r²","source":"../physics/electromagnetism/magnets/#step2","lessons":[{"slug":"magnets","step":2,"category":"physics","stage":"primary","primary":true}],"note":"physics (fields); no atlas group for it. Atlas has no electric-field node, so the edge uses vectors."},
"simple-circuits":{"description":{"zh":"完整闭合的回路才有电流；单回路各处电流相同；短路电流远大于正常值。灯泡电阻取常数，是理想化模型。","en":"Current needs a complete closed loop; in a single loop it is the same everywhere; a short circuit draws far more current than normal. The bulb is a constant resistance, an idealisation."},"formula":"I = V / (R + r)","source":"../physics/circuits/simple-circuits/#step3","lessons":[{"slug":"simple-circuits","step":3,"category":"physics","stage":"primary","primary":true}]},
"ohms-law":{"description":{"zh":"调电压看电流成正比，调电阻看电流按反比变化，对比灯丝的弯曲曲线，用功率公式与电池内阻看能量去向，最后用 R = U/I 测一个未知电阻。直流稳态、集总元件的理想模型。","en":"Tune voltage to see current rise in proportion, tune resistance to see it fall inversely, compare a filament’s bending curve, follow the energy with power and battery internal resistance, then measure a mystery resistor with R = V/I. DC, steady-state, lumped ideal models."},"formula":"I = U / R","source":"../physics/circuits/ohms-law/#step0","lessons":[{"slug":"ohms-law","step":0,"category":"physics","stage":"junior","primary":true}],"note":"simple-circuits is another r1 fragment concept, not yet an atlas node; work-energy is an existing atlas node."},
"series-parallel":{"description":{"zh":"串联时电流处处相同、电压按电阻分；并联时电压相同、电流按电阻反比分；比较等效电阻与灯泡个数的影响，拧下一个灯泡看串并联的差别，计算混联电路，并解释家庭电器并联、保险丝串联。直流、理想电源、恒定电阻的模型。","en":"In series the current is the same and voltage divides by resistance; in parallel the voltage is the same and current divides inversely; compare equivalent resistance and the effect of the number of bulbs, unscrew a bulb to see the difference, solve a mixed circuit, and explain why house appliances are in parallel with a series fuse. DC, ideal source, fixed resistances."},"formula":"R = R₁ + R₂ (串联);  1/R = 1/R₁ + 1/R₂ (并联)","source":"../physics/circuits/series-parallel/#step2","lessons":[{"slug":"series-parallel","step":2,"category":"physics","stage":"junior","primary":true}],"note":"simple-circuits and ohms-law are other fragment concepts (same batch family), not yet atlas nodes."},
"blackbody-radiation":{"description":{"zh":"理想黑体的辐射光谱由温度决定：峰值波长 λmax = b/T，总功率 σT⁴；经典理论在短波发散（紫外灾难），普朗克的能量量子 hν 让光谱收敛。理想黑体模型，真实物体发射率小于 1。","en":"The spectrum of an ideal blackbody is set by its temperature: peak wavelength λmax = b/T, total power σT⁴; classical theory diverges at short wavelengths (the ultraviolet catastrophe) and Planck’s energy quantum hν tames the spectrum. An ideal-blackbody model; real objects have emissivity below 1."},"formula":"M(λ,T) = 2πhc²/λ⁵ · 1/(e^{hc/λkT} − 1)","source":"../physics/modern/blackbody-radiation/#step5","lessons":[{"slug":"blackbody-radiation","step":5,"category":"physics","stage":"senior","primary":true}],"note":"No thermal-physics group in the atlas; group left OTHER. Edge sources point to existing site pages merged separately."},
"electric-fields":{"description":{"zh":"静止点电荷的电场、叠加、场线、等势线与试探电荷运动；二维教学模型，k = 1，真空，不含导体与磁场。","en":"Fields of stationary point charges: superposition, field lines, equipotentials and a released test charge. A 2D teaching model with k = 1 in vacuum, without conductors or magnetism."},"formula":"E = kq/r², E = −∇V","source":"../physics/electromagnetism/electric-fields/#step2","lessons":[{"slug":"electric-fields","step":2,"category":"physics","stage":"senior","primary":true}],"note":"group circuits is the closest of the five existing atlas groups; the page is electrostatics, not circuits"},
"electrochemistry":{"description":{"zh":"两个电极“推电子”的本事不同（标准电极电势），接起来就有电压；放电时反应物减少、产物增多，按能斯特方程电压逐渐降低；充电就是用电把这个过程倒推回去，电解与法拉第定律管的正是这笔电与化学物质之间的账。理想标准状态模型，忽略过电势与内阻。","en":"Two electrodes differ in how hard they push electrons (standard electrode potentials), so joining them gives a voltage. As discharge consumes reactants and builds up products, the Nernst equation says the voltage sags; charging pushes the whole process backwards, and electrolysis with Faraday's law keeps the ledger between charge and chemicals. An ideal standard-state model ignoring overpotential and internal resistance."},"formula":"E = E° − (0.0592/n) log₁₀ Q","source":"../chemistry/reactions/electrochemistry/#step2","lessons":[{"slug":"electrochemistry","step":2,"category":"chemistry","stage":"senior","primary":true}]},
"electromagnetic-induction":{"description":{"zh":"磁通量变化越快，感应电压越大（法拉第定律）；感应电流的方向总要反抗这个变化（楞次定律），就像线圈转动发电时，磁通量一圈一圈周期变化，电压也就成了交流。偶极子近似的教学模型，不含自感与电阻。","en":"The faster the magnetic flux changes, the larger the induced voltage (Faraday's law); the induced current always acts to oppose that change (Lenz's law). Spin a coil and its flux varies periodically, so the voltage comes out as alternating current. A dipole-approximation teaching model without self-inductance or resistance."},"formula":"ε = −N dΦ/dt","source":"../physics/electromagnetism/electromagnetic-induction/#step1","lessons":[{"slug":"electromagnetic-induction","step":1,"category":"physics","stage":"senior","primary":true}],"note":"group circuits is the closest existing atlas group"},
"magnetic-force":{"description":{"zh":"磁场力总垂直于速度，只改方向不改大小，所以带电粒子被弯成圆周运动；转一圈的时间与速度无关，只由电荷、质量和磁场定——质谱仪正是按这个周期（实际按半径）把不同质量的粒子分开，速度选择器则只放行特定速度的粒子。经典、单粒子、教学单位。","en":"A magnetic force is always perpendicular to velocity, so it changes direction but not speed, bending a charged particle into a circle. The time per lap does not depend on speed, only on charge, mass and field — a mass spectrometer separates particles by this period (in practice by radius), and a velocity selector passes only one speed. Classical, single particle, teaching units."},"formula":"F = qv×B, r = mv/(qB)","source":"../physics/electromagnetism/magnetic-force/#step1","lessons":[{"slug":"magnetic-force","step":1,"category":"physics","stage":"senior","primary":true}],"note":"group circuits is the closest existing atlas group; the page is magnetostatics"},
"boost":{"description":{"zh":"先给电感储能，再让电源与电感共同向输出供能。周期平均电压 ⟨Vout⟩ 的关系采用理想小纹波周期稳态近似，要求恒定直流输入、连续导通 CCM（电感电流全周期不归零）及 0<D<1；瞬时值可有纹波。","en":"Store energy in an inductor, then let source and inductor feed the output. The relation for cycle-average voltage ⟨Vout⟩ uses the ideal small-ripple periodic steady-state approximation with constant DC input, CCM (inductor current never zero) and0<D<1; instantaneous voltage can ripple."},"formula":"⟨Vout⟩ ≈ Vin / (1−D)","source":"../physics/circuits/power-converters/#step5","lessons":[{"slug":"power-converters","step":null,"category":"physics","stage":"university","primary":true}]},
"buck":{"description":{"zh":"电源间歇接入。连续导通 CCM 指电感电流全周期不归零，不是恒定电流。理想周期稳态、直流输入恒定时，周期平均输出电压 ⟨Vout⟩ 为 D 倍输入；瞬时值可有纹波。","en":"CCM means inductor current never reaches zero during a cycle, not that it stays constant. With ideal components, periodic steady state and constant DC input, cycle-average output voltage ⟨Vout⟩ is D times input; instantaneous voltage can ripple."},"formula":"⟨Vout⟩ = D Vin","source":"../physics/circuits/power-converters/#step4","lessons":[{"slug":"power-converters","step":null,"category":"physics","stage":"university","primary":true}]},
"capacitor":{"description":{"zh":"像一个极小的蓄水池：流入正端的电流给它充电、电压随存量上升，断开后理想电容在零电流时保持已有电压——电压就是它的“满度”，电流就是进出水流。","en":"Like a tiny reservoir: current into the positive terminal charges it and voltage rises with the stored amount; disconnected, an ideal capacitor holds its voltage at zero current — voltage is its fullness, current the inflow and outflow."},"formula":"iC = C dv/dt","source":"../physics/circuits/power-converters/#step2","lessons":[{"slug":"power-converters","step":null,"category":"physics","stage":"university","primary":true}]},
"carnot-cycle":{"description":{"zh":"在 p–V 图上用等温与绝热四步围成回路：净功是围出的面积，Q_h = W + Q_c，效率上限 1 − T_c/T_h；倒转后是制冷机，COP = T_c/(T_h − T_c)。可逆理想气体模型，真实热机效率更低。","en":"Four isothermal and adiabatic steps close into a loop on a p–V diagram: net work is the enclosed area, Q_h = W + Q_c, the efficiency ceiling is 1 − T_c/T_h, and reversed it is a refrigerator with COP = T_c/(T_h − T_c). A reversible ideal-gas model; real engines do worse."},"formula":"η = 1 − T_c/T_h","source":"../physics/thermal/carnot-cycle/#step4","lessons":[{"slug":"carnot-cycle","step":4,"category":"physics","stage":"university","primary":true}],"note":"No thermal-physics group in the atlas; group left OTHER. Edges use existing atlas node work-energy and site pages merged separately."},
"inductor":{"description":{"zh":"像电路里的飞轮：电感两端电压决定电流的变化速度，电流有了“惯性”——有限电压不能使电流瞬间跳变，只能慢慢推着它变快或变慢。","en":"Like a flywheel in a circuit: voltage across an inductor sets the rate of current change, giving current inertia — finite voltage cannot make current jump instantly, only push it faster or slower over time."},"formula":"vL = L di/dt","source":"../physics/circuits/power-converters/#step1","lessons":[{"slug":"power-converters","step":null,"category":"physics","stage":"university","primary":true}]},
"power":{"description":{"zh":"电压是每份电荷携带的能量，电流是每秒流过的电荷；两者相乘就是每秒的能量，即功率——100 瓦的灯泡每秒用掉 100 焦耳。","en":"Voltage is energy per charge, current is charge per second; multiplied they give energy per second, which is power — a 100-watt bulb uses 100 joules every second."},"formula":"P = VI","source":"../physics/circuits/power-converters/#step0","lessons":[{"slug":"power-converters","step":null,"category":"physics","stage":"university","primary":true}]},
"pwm":{"description":{"zh":"在固定周期内改变开关导通时间来“假装”调光：开关闪得比眼睛反应快时，眼睛只感受到平均亮度——占空比（导通时间占周期的比例）越大，看起来越亮。","en":"Vary switch ON time within a fixed period to fake dimming: flickering faster than the eye can follow, only the average brightness is seen — a larger duty cycle, the fraction of the period spent ON, looks brighter."},"formula":"D = ton / T","source":"../physics/circuits/power-converters/#step3","lessons":[{"slug":"power-converters","step":null,"category":"physics","stage":"university","primary":true}]},
"switch-diode":{"description":{"zh":"开关是可控的门（Buck/Boost 里轮流开关搬运能量），二极管是只推不拉的单向门：开关断开瞬间，电感电流靠它续流不断——没有它，电流无路可走、电压会冲高。","en":"A switch is a controllable gate (Buck and Boost converters shuttle energy by switching in turn); a diode is a one-way gate that only pushes, never pulls: the instant a switch opens, the inductor current keeps flowing through it — without it the current would have nowhere to go and the voltage would spike."},"formula":"route current","source":"../physics/circuits/power-converters/#step3","lessons":[{"slug":"power-converters","step":null,"category":"physics","stage":"university","primary":true}]}
}});
